var mv=null, _mnow=netPadNow(), _md=0;
for(var _mi=12;_mi<=15;_mi++){ var _mh=!!pressed(_mi); PAD.prev[_mi]=_mh; if(_mh&&!_md) _md=_mi; }
if(_md){
