    mv=_md===12?[0,-1]:_md===13?[0,1]:_md===14?[-1,0]:[1,0];
    PAD.mDAt=_mnow+0.4;
  }else if(_mnow+1e-9>=PAD.mDAt){
    mv=_md===12?[0,-1]:_md===13?[0,1]:_md===14?[-1,0]:[1,0];
    PAD.mDAt=_mnow+0.1;
  }
}else PAD.mDAt=null;
PAD.mDdir=_md; PAD.mDmd=md;
